mapper.update:
UPDATE tb_payment SET status = #{callback.result}, update_user_id = #{userId},
    confirmed_at = strftime('%Y-%m-%dT%H:%M:%fZ', 'now'), updated_at = strftime('%Y-%m-%dT%H:%M:%fZ', 'now')
WHERE id = #{callback.paymentId} AND order_id = #{callback.orderId} AND shop_id = #{shopId}
    AND pay_type = #{callback.payType} AND amount = #{callback.amount} AND channel_trade_no = #{callback.channelTradeNo}
    AND status = 'PENDING' AND created_user_id = #{userId}
    AND EXISTS (SELECT 1 FROM tb_order o WHERE o.id = tb_payment.order_id
        AND o.shop_id = #{shopId} AND o.created_user_id = #{userId} AND o.status = 'WAIT_PAY')
